UPDATE services SET
  title         = $t63$Kadr kargüzarlığı və HR audit$t63$,
  summary       = $t64$Kadr uçotunun qanunvericiliyə uyğun təşkili, HR sənəd şablonları, outsorsinq və kadr auditi.$t64$,
  description   = $t65$<p>Müəssisənizdə kadr sənədlərinin düzgün aparılmaması gələcəkdə ciddi hüquqi problemlərə və inzibati cərimələrə səbəb ola bilər. Kadr xidmətlərimiz məhz bu risklərin qarşısını almaq üçün nəzərdə tutulub.</p>
<h2>1. Kadr uçotunun təşkili</h2>
<ul>
<li>Kadr uçotunun AR qanunvericiliyinə uyğun təşkili</li>
<li>İcbari sığorta əməliyyatlarının icrası</li>
<li>Əməkdaşların şəxsi işlərinin yaradılması</li>
<li>Xəstəlik vərəqəsinin rəsmiləşdirilməsi</li>
<li>Əmək müqavilələrinin tərtibatı</li>
<li>Lokal normativ aktların hazırlanması</li>
<li>Ştat cədvəlinin tərtib edilməsi</li>
<li>İşçilərin EHP-də rəsmi qeydiyyata alınması</li>
</ul>
<h2>2. İnsan resursları şablonları</h2>
<p>Peşəkar mütəxəssislər tərəfindən insan resurslarının idarə edilməsi üzrə ehtiyac duyulan istənilən qaydanın və sənəd şablonlarının hazırlanması.</p>
<h2>3. Outsorsinq xidməti</h2>
<p>Peşəkar mütəxəssislərdən ibarət komandamızla outsorsinq xidməti formasında kadr kargüzarlığının həyata keçirilməsi — xərclərə qənaət edərək.</p>
<h2>4. Kadr auditi</h2>
<p>Biznesdə maliyyə və hüquqi risklərin müəyyən edilməsi, nöqsanların aşkarlanması və onların qarşısının alınması.</p>$t65$,
  icon          = $t66$users$t66$,
  image_url     = $t67$/services/kadr.webp$t67$,
  title_i18n       = jsonb_set(coalesce(title_i18n, '{}'::jsonb),       '{az}', to_jsonb($t68$Kadr kargüzarlığı və HR audit$t68$::text)),
  summary_i18n     = jsonb_set(coalesce(summary_i18n, '{}'::jsonb),     '{az}', to_jsonb($t69$Kadr uçotunun qanunvericiliyə uyğun təşkili, HR sənəd şablonları, outsorsinq və kadr auditi.$t69$::text)),
  description_i18n = jsonb_set(coalesce(description_i18n, '{}'::jsonb), '{az}', to_jsonb($t70$<p>Müəssisənizdə kadr sənədlərinin düzgün aparılmaması gələcəkdə ciddi hüquqi problemlərə və inzibati cərimələrə səbəb ola bilər. Kadr xidmətlərimiz məhz bu risklərin qarşısını almaq üçün nəzərdə tutulub.</p>
