-- ── faq_items: new table backing the homepage FAQ + FAQPage schema ────────
CREATE TABLE IF NOT EXISTS faq_items (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question    text NOT NULL,
  answer      text NOT NULL,
  sort_order  int  NOT NULL DEFAULT 0,
  is_published boolean NOT NULL DEFAULT true,
  question_i18n jsonb NOT NULL DEFAULT '{}'::jsonb,
  answer_i18n   jsonb NOT NULL DEFAULT '{}'::jsonb
);

ALTER TABLE faq_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public read faq_items" ON faq_items;
CREATE POLICY "Public read faq_items" ON faq_items
  FOR SELECT TO public USING (is_published);
DROP POLICY IF EXISTS "Admin all faq_items" ON faq_items;
CREATE POLICY "Admin all faq_items" ON faq_items
  FOR ALL TO authenticated USING (true) WITH CHECK (true);

