INSERT INTO faq_items (question, answer, sort_order, question_i18n, answer_i18n) VALUES (
  $t140$Əcnəbi işçilər üçün iş icazəsini nə qədər müddətə alırsınız?$t140$, $t141$Müddət sənədlərin tamlığından və Dövlət Miqrasiya Xidmətinin baxış müddətindən asılıdır. Sənədlərin hazırlanmasından təhvilinə qədər bütün prosesi aparır və müddətlərə nəzarət edirik.$t141$, 6,
